/* Lot 107: relative heights and max-height from the reader laid out by the engine (generated by scripts/lot107_gen.py; expectations from scripts/lot107_model.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "webeng.h"
#include "wf_html.h"

static we_doc_t g_doc;
static wf_geom_t g_g;
static char g_html[8192], g_out[65536], g_o[512];
static int g_at, g_c;

static int min_i(int a, int b) { return a < b ? a : b; }

/* the page with n lines in #o (#i first), reduced by the reader with
 * marks, laid out at 640 x 480 */
static void pass(const char *css, int n) {
    wf_html_stats_t st;
    int k, l;
    l = snprintf(g_html, sizeof(g_html), "<html><head><style>@keyframes k { from { color: #000000 } to { color: "
                 "#ffffff } } %s</style></head><body><main><div id=o><p id=i>i</p>", css);
    for (k = 1; k < n; k++) l += snprintf(g_html + l, sizeof(g_html) - (size_t)l, "<p>line %d</p>", k);
    snprintf(g_html + l, sizeof(g_html) - (size_t)l, "</div><p>after</p></main></body></html>");
    wf_html_set_sitecss(1);
    wf_html_set_geommarks(1);
    k = wf_html_reduce(g_html, (int)strlen(g_html), 0, g_out, (int)sizeof(g_out), &st);
    wf_html_set_geommarks(0);
    wf_html_set_sitecss(0);
    TEST_ASSERT_TRUE(k > 0);
    TEST_ASSERT_EQUAL(0, we_parse(&g_doc, g_out, k));
    TEST_ASSERT_EQUAL(0, we_style(&g_doc));
    TEST_ASSERT_EQUAL(0, we_layout_viewport(&g_doc, 640, 480));
    memset(&g_g, 0, sizeof(g_g));
    (void)we_geom_feed(&g_doc, "wg", &g_g);
}

/* the style the reader writes on the marked box #o; g_at its mark */
static const char *flow(const char *css, int n) {
    const char *p, *q;
    pass(css, n);
    p = strstr(g_out, "<div id=\"wg");
    if (!p) return "NO MARK";
    for (g_at = 0, q = p + 11; *q >= '0' && *q <= '9'; q++) g_at = g_at * 10 + (*q - '0');
    p = strstr(p, "style=\"");
    if (!p) return "NO STYLE";
    p += 7;
    q = strchr(p, '"');
    snprintf(g_o, sizeof(g_o), "%.*s", (int)(q - p), p);
    return g_o;
}

/* the content height of n lines: the same box and font sizes with a
 * large max-height */
static int content_h(const char *css, int n) {
    (void)flow(css, n);
    return g_g.box[g_at].b_size;
}

static void test_l107_flow_0(void) {
    g_c = content_h("html { font-size: 12px } #o { overflow: auto; max-height: 1999px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 15);
    TEST_ASSERT_EQUAL_STRING("overflow-y:auto;max-height:36px", flow("html { font-size: 12px } #o { overflow: hidden auto; max-height: 3rem } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 15));
    TEST_ASSERT_EQUAL(min_i(36, g_c), g_g.box[g_at].s_vp);
    TEST_ASSERT_EQUAL(g_g.box[g_at].s_vp, g_g.box[g_at].b_size);
    TEST_ASSERT_EQUAL(1, g_g.box[g_at].sv);
    g_c = content_h("html { font-size: 20px } #o { overflow: auto; max-height: 1999px; font-size: 20px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 3);
    TEST_ASSERT_EQUAL_STRING("font-size:20px;overflow-y:scroll;max-height:96px", flow("html { font-size: 20px } #o { max-height: 20vh; overflow: scroll; font-size: 20px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 3));
    TEST_ASSERT_EQUAL(min_i(96, g_c), g_g.box[g_at].s_vp);
    TEST_ASSERT_EQUAL(g_g.box[g_at].s_vp, g_g.box[g_at].b_size);
    TEST_ASSERT_EQUAL(1, g_g.box[g_at].sv);
    g_c = content_h("html { font-size: 10px } #o { overflow: auto; max-height: 1999px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 8);
    TEST_ASSERT_EQUAL_STRING("overflow-y:auto;max-height:96px", flow("html { font-size: 10px } #o { overflow: auto; max-height: 6pc } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 8));
    TEST_ASSERT_EQUAL(min_i(96, g_c), g_g.box[g_at].s_vp);
    TEST_ASSERT_EQUAL(g_g.box[g_at].s_vp, g_g.box[g_at].b_size);
    TEST_ASSERT_EQUAL(1, g_g.box[g_at].sv);
    g_c = content_h("html { font-size: 20px } #o { overflow: auto; max-height: 1999px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 3);
    TEST_ASSERT_EQUAL_STRING("overflow-y:scroll;max-height:50px", flow("html { font-size: 20px } #o { max-height: 2.5em; overflow: scroll } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 3));
    TEST_ASSERT_EQUAL(min_i(50, g_c), g_g.box[g_at].s_vp);
    TEST_ASSERT_EQUAL(g_g.box[g_at].s_vp, g_g.box[g_at].b_size);
    TEST_ASSERT_EQUAL(1, g_g.box[g_at].sv);
    TEST_ASSERT_EQUAL_STRING("font-size:8px;overflow-y:scroll;height:96px", flow("html { font-size: 24px } #o { font-size: 8px; overflow: scroll; height: 20vh } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 24));
    TEST_ASSERT_EQUAL(96, g_g.box[g_at].s_vp);
    TEST_ASSERT_EQUAL(g_g.box[g_at].s_vp, g_g.box[g_at].b_size);
    TEST_ASSERT_EQUAL(1, g_g.box[g_at].sv);
    g_c = content_h("#o { overflow: auto; max-height: 1999px } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 8);
    TEST_ASSERT_EQUAL_STRING("overflow-y:auto;max-height:48px", flow("#o { max-height: 3rem; overflow: hidden auto } #i { animation: k 1s linear; animation-timeline: scroll(nearest) }", 8));
    TEST_ASSERT_EQUAL(min_i(48, g_c), g_g.box[g_at].s_vp);
    TEST_ASSERT_EQUAL(g_g.box[g_at].s_vp, g_g.box[g_at].b_size);
    TEST_ASSERT_EQUAL(1, g_g.box[g_at].sv);
}

